import {ports,cruises} from './data.js';
import {registerPort} from './ncl.js';
import {findNorthAfricanPort} from './north-africa.js';
const origin='https://www.cruise.ca',base=origin+'/public-sites/api/site/58f45ef4-c253-43dd-b198-141872ed26be/';
const european=new Set([35,41,53,59,65,71,77,83]);
const initialFeed=()=>({loading:false,error:null,page:0,hasMore:false,totalItineraries:0,loadedItineraries:0,checkedAt:null,failedItineraries:0});
const escape=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
export function media(path){if(typeof path!=='string'||!path.startsWith('/images/')||path.includes('..'))return null;return new URL(path,'https://media.cruise.ca').href;}
const named={valencia:'VLC',alicante:'ALC',tarragona:'TAR',coruna:'LCG',dover:'DOV',warnemunde:'WAR',barcelona:'BCN',marseille:'MRS',civitavecchia:'CIV',rome:'CIV',naples:'NAP',messina:'MSN',palma:'PMI',ibiza:'IBZ',ajaccio:'AJA',valletta:'MLA',athens:'PIR',piraeus:'PIR',santorini:'JTR',mykonos:'JMK',dubrovnik:'DBV',kotor:'KOT',bergen:'BGO',copenhagen:'CPH',kiel:'KIE',stockholm:'STO',helsinki:'HEL',tallinn:'TLL',southampton:'SOU',lisbon:'LIS',cadiz:'CAD',alesund:'AES',geiranger:'GNR',stavanger:'STA',split:'SPU',corfu:'CFU',katakolon:'KAK',kusadasi:'KUS',chania:'CHA',rhodes:'RHO',catania:'CTA',palermo:'PMO',livorno:'LIV',spezia:'SPE',salerno:'SAL',ravenna:'RAV',bari:'BRI',trondheim:'TRD',flam:'FLM',olden:'OLD',haugesund:'HAU',kristiansand:'KRS',reykjavik:'REY',akureyri:'AKU',isafjordur:'ISA',leixoes:'LXO',funchal:'FNC',tangier:'TNG',gibraltar:'GIB',cartagena:'CAR',talinn:'TLL',visby:'VIS',oslo:'OSL',klaipeda:'KLA',riga:'RIX',gdynia:'GDY',belfast:'BEL',cobh:'COB',cork:'COB',dublin:'DUB',liverpool:'LIVP',greenock:'GRK',invergordon:'INV',edinburgh:'EDI',lerwick:'LER',kirkwall:'KIR',heraklion:'HER',istanbul:'IST',zeebrugge:'ZEE',leghorn:'LIV',piraieus:'PIR',valetta:'MLA',ephesus:'KUS',bodrum:'BOD',amsterdam:'AMS',rotterdam:'ROT',brugge:'ZEE',zadar:'ZAD'};
const extra={sandnes:[58.85,5.74],skjolden:[61.49,7.6],brindisi:[40.64,17.94],trieste:[45.65,13.77],skagen:[57.72,10.59],aarhus:[56.15,10.22],kristiansund:[63.11,7.73],savona:[44.31,8.48],olbia:[40.92,9.5],portoferraio:[42.81,10.33],trapani:[38.02,12.51],toulon:[43.1,5.88],malaga:[36.71,-4.42],genoa:[44.41,8.91]};
function portId(p){const id=sourcePortId(p);const port=ports.find(p=>p.id===id);if(port&&Number.isSafeInteger(p.idPort)){port.ratingId=p.idPort;port.ratingName=p.name}return id}
function sourcePortId(p){const african=findNorthAfricanPort(p.name);if(african)return african.id;const name=p.name.normalize('NFD').replace(/[\u0300-\u036f]/g,'').toLowerCase();const matched=Object.keys(named).find(n=>name.includes(n));if(matched)return registerPort({code:named[matched],title:p.name});const xy=Object.entries(extra).find(([n])=>name.includes(n))?.[1],id='costa-'+p.idPort;let existing=ports.find(p=>p.id===id);if(!existing){existing={id,name:escape(p.name),country:'',lat:xy?.[0],lon:xy?.[1]};ports.push(existing)}return id;}
// Read JSON records from the public React Flight payload. Text records use UTF-8 byte lengths.
export function parseDetail(html,id){const chunks=[...html.matchAll(/self\.__next_f\.push\(\[1,("(?:[^"\\]|\\.)*")\]\)/g)].map(m=>JSON.parse(m[1]));const bytes=new TextEncoder().encode(chunks.join('')),decoder=new TextDecoder();let at=0,product,itinerary;function walk(v){if(!v||typeof v!=='object')return;if(v.idCruise===id&&Array.isArray(v.departures)&&typeof v.duration==='number')product={idCruise:v.idCruise,duration:v.duration,currency:v.currency,companyId:v.company?.id,boatId:v.boat?.id,destinationIds:v.destinations?.map(d=>d.id),full:v.full,departures:v.departures.map(s=>({idDepart:s.idDepart,date:s.departureDate,full:s.full,price:s.bestPrice?.cruise?.price,priceFull:s.bestPrice?.full,taxesExcludes:s.bestPrice?.taxesExcludes,taxes:s.bestPrice?.taxes}))};if(v.id===id&&Array.isArray(v.steps)&&v.steps.some(s=>typeof s.day==='number'))itinerary=v.steps.map(s=>({day:s.day,idPort:s.idPort,name:s.name,arrival:s.arrival,departure:s.departure,image:media(s.url)}));for(const x of Object.values(v))if(typeof x==='object')walk(x);}
 while(at<bytes.length){if(bytes[at]===10){at++;continue}const colon=bytes.indexOf(58,at);if(colon<0)break;at=colon+1;if(bytes[at]===84){const comma=bytes.indexOf(44,at),length=parseInt(decoder.decode(bytes.slice(at+1,comma)),16);if(comma<0||!Number.isFinite(length))break;at=comma+1+length;continue}let end=bytes.indexOf(10,at);if(end<0)end=bytes.length;try{walk(JSON.parse(decoder.decode(bytes.slice(at,end))))}catch{}at=end+1;}
 if(!product||!itinerary)throw Error('Le format du détail cruise.ca a changé.');return {...product,steps:itinerary};}
export function normalize(item,detail,state,observedAt,company={id:2,key:'costa',name:'Costa Cruises',label:'Costa'}){if(detail.companyId!==company.id||detail.full===true||detail.currency!=='$$CA'||!detail.destinationIds?.some(id=>european.has(id)))return [];const nights=detail.duration-1;if(!Number.isInteger(nights)||nights<1||nights>100)return [];const portSteps=detail.steps.filter(p=>typeof p.name==="string"&&!/^(navigation|at sea|cruising|day at sea)$/i.test(p.name));const paired=company.id===46&&portSteps.length%2===0&&portSteps[0]?.day===0&&portSteps.every((p,i)=>i%2===1||portSteps[i+1]?.idPort===p.idPort&&portSteps[i+1]?.day===p.day+1);const steps=paired?portSteps.filter((p,i)=>i%2===1):portSteps;const stops=[...new Map(steps.filter(p=>typeof p.name==='string'&&!/^(navigation|at sea|cruising|day at sea)$/i.test(p.name)&&Number.isFinite(p.day)).map(p=>({...p,id:portId(p),name:escape(p.name)})).map(p=>[p.day+':'+p.id,p])).values()];if(!stops.length)return [];const region=detail.destinationIds.some(id=>[41,53,65].includes(id))?'north':detail.destinationIds.includes(71)?'greek':'west';
 return detail.departures.flatMap(s=>{if(s.full!==false||s.priceFull!==false||!Number.isFinite(s.price)||s.price<=0||!Number.isSafeInteger(s.idDepart)||!/^\d{4}-\d{2}-\d{2}$/.test(s.date))return [];const endDate=new Date(Date.parse(s.date+'T12:00:00Z')+nights*864e5).toISOString().slice(0,10);if(s.date<state.start||endDate>state.end)return [];if(s.taxesExcludes&&(!Number.isFinite(s.taxes)||s.taxes<0))return [];const price=s.price+(s.taxesExcludes?s.taxes:0);return [{id:company.key+'-'+item.id+'-'+s.idDepart,title:escape(item.name),company:company.name,provider:company.key,sourceName:'cruise.ca',ship:escape(item.boatName),shipRatingId:detail.boatId,date:s.date,endDate,nights,price,currency:'CAD',cabin:'Tarif de l’agence',taxesIncluded:!s.taxesExcludes,region,ports:stops.map(p=>p.id),stops,image:stops.find(p=>p.image)?.image||media(item.boatImg),sourceUrl:new URL(item.link,origin).href,observedAt,live:true}];});}
export function createAgencyProvider(company){
const feed=initialFeed();
let controller,version=0;const cache=new Map();function cancel(){controller?.abort();version++;feed.loading=false;}
async function get(url,signal,detailId){const old=cache.get(url);if(old&&Date.now()-old.time<300000)return old;const response=await fetch(url,{signal,credentials:'omit'});if(!response.ok)throw Error('La source '+company.label+' (cruise.ca) est indisponible.');const value=detailId?parseDetail(await response.text(),detailId):await response.json();const stored={value,time:Date.now()};cache.set(url,stored);if(cache.size>150)cache.delete(cache.keys().next().value);return stored;}
async function loadCruises(state,append=false,onUpdate=()=>{}){controller?.abort();controller=new AbortController();const signal=controller.signal,run=++version;feed.loading=true;feed.error=null;if(!append)Object.assign(feed,{page:0,totalItineraries:0,loadedItineraries:0,failedItineraries:0});onUpdate();try{if(!/^\d{4}-\d{2}-\d{2}$/.test(state.start)||!/^\d{4}-\d{2}-\d{2}$/.test(state.end)||state.start>state.end)throw Error('Choisissez une période valide.');const params=new URLSearchParams({cmp:String(company.id),dst:[...european].join(','),rs:'12',pgn:String(feed.page),ddGte:state.start,ddLte:state.end,lang:'en'});const raw=await get(base+'search/results?'+params,signal),catalog=raw.value;if(catalog.currency!=='CAD'||!Array.isArray(catalog.results)||!Number.isFinite(catalog.count))throw Error('La source '+company.label+' n’a pas confirmé des offres en CAD.');feed.totalItineraries=catalog.count;let index=0,failed=0;const output=[];await Promise.all(Array.from({length:Math.min(4,catalog.results.length)},async()=>{while(index<catalog.results.length){const item=catalog.results[index++];try{if(!Number.isSafeInteger(item.id)||item.companyName!==(company.catalogName||company.name)||!/^\/f-\d+-[a-z0-9-]+$/.test(item.link))throw Error('Offre '+company.label+' invalide');const parsed=await get(origin+item.link,signal,item.id);output.push(...normalize(item,parsed.value,state,new Date(parsed.time).toISOString(),company));}catch(e){if(signal.aborted)throw e;failed++;}}}));if(run!==version)return;if(failed&&failed===catalog.results.length)throw Error('Les détails '+company.label+' sont indisponibles.');const ids=new Set(cruises.map(c=>c.id));for(const c of output)if(!ids.has(c.id)){cruises.push(c);ids.add(c.id)}feed.failedItineraries+=failed;feed.loadedItineraries+=catalog.results.length;feed.page++;feed.hasMore=feed.page*12<catalog.count;feed.checkedAt=new Date(raw.time).toISOString();}catch(e){if(run===version&&!signal.aborted){feed.error=company.label+' : '+e.message;feed.hasMore=false;}}finally{if(run===version){feed.loading=false;onUpdate();}}}

return {feed,cancel,loadCruises,normalize:(item,detail,state,observedAt)=>normalize(item,detail,state,observedAt,company)};
}
